sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {    
    updateMitigatedSeverityChoices();
}

function updateMitigatedSeverityChoices() {
    var intrinsicSeverity = g_form.getValue('severity');

    // Define your severity choice mappings
    var severityChoices = {
        '1': '1.Minor - Injuries that could require first aid treatment',
        '2': '2.Moderate - Injuries that require medical attention with return to work generally within 3 days',
        '3': '3.Serious - Injuries that require medical attention with return to work likely after 3 days',
        '4': '4.Major - Injuries that require medical attention with worker suffering long-term reduction in qual',
        '5': '5.Fatal - Injuries that result in immediate death or subsequent death'
    };

    if (intrinsicSeverity) {
        // Store the current value before clearing
        var currentMitigatedSeverity = g_form.getValue('mitigated_severity');

        g_form.clearOptions('mitigated_severity');
        g_form.addOption('mitigated_severity', '', '-- None --');

        // Add options with proper display labels
        for (var j = 1; j <= parseInt(intrinsicSeverity); j++) {
            var valueStr = j.toString();
            var displayText = severityChoices[valueStr] || valueStr;
            g_form.addOption('mitigated_severity', valueStr, displayText);
        }

        // Restore the value if it's still valid, otherwise clear it
        if (currentMitigatedSeverity) {
            if (parseInt(currentMitigatedSeverity) <= parseInt(intrinsicSeverity)) {
                // Use setTimeout to ensure options are fully populated
                setTimeout(function() {
                    g_form.setValue('mitigated_severity', currentMitigatedSeverity);
                }, 100);
            } else {
                g_form.setValue('mitigated_severity', '');
            }
        }
    } else {
        // Clear the field if no intrinsic severity is set
        g_form.clearOptions('mitigated_severity');
        g_form.addOption('mitigated_severity', '', '-- None --');
        g_form.setValue('mitigated_severity', '');
    }
}
